package com.loopers.interfaces.consumer;
import org.apache.kafka.clients.admin.*;import org.apache.kafka.clients.consumer.*;import org.apache.kafka.common.*;import org.apache.kafka.common.serialization.StringDeserializer;import org.testcontainers.kafka.KafkaContainer;import org.testcontainers.utility.DockerImageName;import java.time.Duration;import java.util.*;
final class KafkaExperimentSupport implements AutoCloseable{final KafkaContainer broker=new KafkaContainer(DockerImageName.parse("apache/kafka-native:3.8.0"));KafkaExperimentSupport(){broker.start();}void topic(String name,int partitions)throws Exception{try(Admin a=Admin.create(Map.of(AdminClientConfig.BOOTSTRAP_SERVERS_CONFIG,broker.getBootstrapServers()))){a.createTopics(List.of(new NewTopic(name,partitions,(short)1))).all().get();}}KafkaConsumer<String,String> consumer(String group,String id){Properties p=new Properties();p.put(ConsumerConfig.BOOTSTRAP_SERVERS_CONFIG,broker.getBootstrapServers());p.put(ConsumerConfig.GROUP_ID_CONFIG,group);p.put(ConsumerConfig.CLIENT_ID_CONFIG,id);p.put(ConsumerConfig.GROUP_INSTANCE_ID_CONFIG,id);p.put(ConsumerConfig.ENABLE_AUTO_COMMIT_CONFIG,"false");p.put(ConsumerConfig.AUTO_OFFSET_RESET_CONFIG,"earliest");p.put(ConsumerConfig.PARTITION_ASSIGNMENT_STRATEGY_CONFIG,"org.apache.kafka.clients.consumer.RangeAssignor");p.put(ConsumerConfig.KEY_DESERIALIZER_CLASS_CONFIG,StringDeserializer.class);p.put(ConsumerConfig.VALUE_DESERIALIZER_CLASS_CONFIG,StringDeserializer.class);return new KafkaConsumer<>(p);}public void close(){broker.stop();}}
